D[1722]={"^Aspect of the Viper %- Reduces the damage and healing penalty by (.-)%%%.\n\nAspect of the Monkey %- Reduces the damage done to you while active by (.-)%%%.\n\nAspect of the Hawk %- Increases the attack power bonus by (.-)%%%.%s*$","Aspecto dá Víbora - Reduz a penalidade dano e cura em {{1}}%.\n\nAspecto do Macaco - Reduz o dano que recebe enquanto está ativado em {{2}}%.\n\nAspecto do Falcão - Aumenta o bônus de poder de ataque em {{3}}%."}
D[2650]={"^|cFF66DDFFLevel 10 Passive|r\nYou now gain Intellect equal to your Strength%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nAgora ganha Intelecto igual a sua Força."}
D[2652]={"^|cFF66DDFFLevel 10 Passive|r\nYour |cffffffffHuntress Shot|r now has a |cffffffffLunar Eclipse|r effect%.\n\n|cFFFFFFFFHuntress Shot|r: Applies 2 additional |cff66ccffScattered Stars|r%.%s*$","|cFF66DDFFPassivo de Nível 10|r\nSeu |cffffffffDisparo de Caçadora|r agora tem um efeito de |cffffffffEclipse Lunar|r.\n\n|cFFFFFFFFDisparo de Caçadora|r: Aplica 2 Estrelas Dispersas adicionais |cff66ccffEstrelas Dispersas|r."}
D[3768]={"^Increases the damage of |cffffffffLunar Lance|r by (.-)%%%.%s*$","Aumenta o dano de |cffffffffLança Lunar|r em {{1}}%."}
D[3772]={"^Increases the bonus healing scaling of |cFFFFFFFFMoonwell Splash|r and the healing done through |cFFFFFFFFAspect of the Goddess|r by (.-)%%%.%s*$","Aumenta a escala de cura adicional de |cFFFFFFFFOnda do Poço Lunar|r e a cura realizadatravés de |cFFFFFFFFAspecto da Deusa|r em {{1}}%."}
D[3775]={"^Blast the target enemy and all enemies near them with lunar fire that deals (.-) Arcane damage, applying |cff66ccffScattered Stars|r%.\n\nConsuming a |cff66ccffScattered Star|r reduces the remaining cooldown by (.-) sec%.%s*$","Golpeia o alvo e todos os inimigos próximos com fogo lunar que causa {{1}} de dano Arcano, aplicando |cff66ccffEstrelas Dispersas|r.\n\nConsumir uma |cff66ccffEstrela Dispersa|r reduz a recarga restante em {{2}} s."}
D[4229]={"^Strike an enemy for (.-)%% Weapon Damage plus (.-) and regenerate (.-)%% of your maximum mana plus (.-)%.%s*$","Golpeia um inimigo em {{1}}% dano da arma mais {{2}} e regenera o {{3}}% do máximo de mana que possui mais {{4}}."}
D[4230]={"^Sprint forward with astral magic at your feet, increasing your movement speed by (.-)%% for (.-)%. \n\nWhile active, you cannot be slowed and cannot stop moving%.%s*$","Avança rapidamente com magia astral sob seus pés, aumentando sua velocidade de movimento em {{1}}% durante {{2}}.\n\nEnquanto estiver ativo, você não pode ser desacelerado nem parar de se mover."}
D[4231]={"^Causes (.-) Arcane damage to up to (.-) enemies within (.-)yd of the target, scaling with attack power and Intellect%.\n\nCan only be used after parrying an attack%. This attack cannot be avoided%.%s*$","causa {{1}} de dano Arcano a até {{2}} inimigos em um raio de {{3}} m do alvo, escalando com o poder de ataque Intelecto.\n\nSó pode ser usada depois de aparar um ataque. Este ataque não pode ser esquivado."}
D[4232]={"^You call an Astral Flare down from the sky, dealing (.-) Arcane Damage to an enemy and regenerating (.-)%% of your Maximum |cff01cdfeMana|r%.%s*$","Invoca uma |cffffffffLabareda Astral|r do céu, causando {{1}} de dano Arcano a um inimigo e regenerando {{2}}% da sua |cff01cdfeMana|r máxima."}
D[4233]={"^|cff66ccffConsumes Scattered Stars|r\nUnleash a lunar lance on an enemy, dealing (.-) Arcane damage plus (.-) every (.-) seconds for (.-)%.%s*$","|cff66ccffConsome Estrelas dispersas|r\nDesata uma Lança Lunar sobre um inimigo, causando {{1}} de dano Arcano mais {{2}} a cada {{3}} segundos durante {{4}}."}
