T[14520]={"^Reduces the cooldown of |cffffffffBubble Buddy|r by (.-) sec%.%s*$","Reduz a recarga de |cffffffffAmigo Bolha|r em {{1}} s."}
T[14522]={"^|cffffffffAstral Blade|r now increases the damage of the next 3 |cffffffffStarsunders|r against your target by (.-)%%%.%s*$","|cffffffffLâmina Astral|r agora aumenta o dano do próximo 3 |cffffffffRuptura Estelar|r contra seu alvo em {{1}}%."}
T[14688]={"^Gives Celestial Strike a chance to proc Scattered Stars%.%s*$","Dá a Golpe celestial uma chance de ativar Estrelas Dispersas."}
T[14708]={"^Upon reaching 8 stacks, your next Starcall deals increased damage%.%s*$","Ao alcançar 8 acúmulos, seu próximo Chamada a Estrelas causará um dano maior."}
T[14765]={"^Melee and ranged auto attacks now have a (.-)%% chance to apply |cff66ccffScattered Stars|r and deal (.-) Arcane damage%.%s*$","Os ataques automáticos corpo a corpo e à distância agora têm {{1}}% de chance de aplicar |cff66ccffEstrelas Dispersas|r e causar {{2}} de dano Arcano."}
T[14787]={"^Melee and ranged damage dealt has a (.-)%% chance to slow enemy movement speed by (.-)%% for (.-), stacking (.-) times and apply |cff66ccffScattered Stars|r%.%s*$","O dano corpo a corpo e à distância tem {{1}}% de chance de reduzir a velocidade de movimento do inimigo em {{2}}% por {{3}}, acumulando até {{4}} vezes, e aplicar |cff66ccffEstrelas Dispersas|r."}
T[14788]={"^Melee and ranged auto attacks have a (.-)%% chance to strike 3 additional times for (.-)%% of the damage dealt as Arcane damage and apply |cff66ccffScattered Stars|r%.%s*$","Os ataques automáticos corpo a corpo e à distância têm {{1}}% de chance de atingir mais 3 vezes, causando {{2}}% do dano como dano Arcano, e aplicar |cff66ccffEstrelas Dispersas|r."}
T[14791]={"^Increases your critical strike chance by (.-)%%%.\n\nWhile active, ranged critical strikes now reduce the remaining cooldown of all healing spells by 10%% and apply a |cff66ccffScattered Star|r to your target and up to 4 enemies within 5 yds of them%.%s*$","Aumenta sua chance de acerto crítico em {{1}}%.\n\nEnquanto estiver ativo, acertos críticos à distância reduzem em 10% a recarga restante de todos os feitiços de cura e aplicam uma |cff66ccffEstrela Dispersa|r ao alvo e até 4 inimigos em um raio de 5 m dele."}
T[14832]={"^Whenever you are |cffb0f67a|cffb0f67aHealed|r|r, you have a 10%% chance to enable your Vengeance of Elune ability for 10 seconds%.\n\nThis effect can only trigger when a Healing effect actually restores missing health%.%s*$","Sempre que você recebe |cffb0f67a|cffb0f67acura|r|r, há 10% de chance de habilitar |cffffffffVingança de Elune|r durante 10 s.\n\nEste efeito só pode ser ativado quando uma cura realmente restaura vida perdida."}
T[14833]={"^|cFFFFFFFFHuntress Shot|r and |cFFFFFFFFStarcall|r apply an additional stack of |cff66ccffScattered Stars|r%.\n\nAbility attack range increased to 50 yds%.%s*$","|cFFFFFFFFDisparo de Caçadora|r e |cFFFFFFFFChamado Estelar|r aplicam um acúmulo adicional de |cff66ccffEstrelas Dispersas|r.\n\nO alcance das habilidades aumenta para 50 m."}
T[14834]={"^|cFFFFFFFFHuntress Shot|r and |cFFFFFFFFStarcall|r apply an additional stack of |cff66ccffScattered Stars|r%.\n\nAbility attack range increased to 40 yds%.%s*$","|cFFFFFFFFDisparo da Caçadora|r e |cFFFFFFFFChamado Estelar|r aplicam um acúmulo adicional de |cff66ccffEstrelas Dispersas|r.\n\nO alcance de ataque das habilidades aumenta para 40 m."}
T[14835]={"^Vengeance of Elune ability now becomes available after Blocking or Dodging an attack, as well as Parrying%. This effect cannot occur more than once every 3 sec%.%s*$","Agora a habilidade Vingança de Eluna torna-se disponível depois de bloquear, esquiva ou aparar um ataque. Este efeito não pode acontecer mais de uma vez a cada 3 s."}
T[14869]={"^All damage dealt has a (.-)%% chance to strike 3 additional times for (.-)%% of the damage dealt as Arcane Damage and apply |cff66ccffScattered Stars|r%.%s*$","Todo dano causado tem {{1}}% de chance de impactar 3 vezes mais, causando {{2}}% do dano causado como dano Arcano e aplicando |cff66ccffEstrelas Dispersas|r."}
T[14905]={"^Can be consumed by spells to deal additional Arcane Damage%.Arcane Damage taken from the Starcaller increased by (.-)%%%.%s*$","Pode ser consumido por feitiços para causar dano Arcano adicional. O dano Arcano recebido do Conjurador estelar aumenta em {{1}}%."}
T[14906]={"^Can be consumed by spells to deal additional Arcane Damage%.%s*$","Pode ser consumido por feitiços para causar dano Arcano adicional."}
T[14958]={"^Melee and ranged auto attacks now have a (.-)%% chance to drain the target's mana equal to (.-)%% of the damage dealt and apply |cff66ccffScattered Stars|r, but your damage is reduced by (.-)%% while this is active%.%s*$","Ataques automáticos corpo a corpo e à distância têm {{1}}% de chance de drenar mana do alvo equivalente a {{2}}% do dano causado e conceder a você |cff66ccffEstrelas Dispersas|r, mas seu dano é reduzido em {{3}}% enquanto o efeito estiver ativo."}
T[14969]={"^Enables the use of |cffffffffVengeance of Elune|r after Blocking and Dodging as well as Parrying%. Cannot occur more than once every 3 sec%.%s*$","Permite o uso de |cffffffffVingança de Elune|r depois de bloquear, esquiva e aparar. Não pode acontecer mais de uma vez a cada 3 s."}
T[15043]={"^Affected by Scattered Stars%. Arcane Damage taken from the Starcaller increased by (.-)%%%.%s*$","Afetado por Estrelas Dispersas. O dano Arcano recebido do Invocador Estelar aumenta em {{1}}%."}
T[17338]={"^Damage done by your Fireball and Pyroblast spells increased by (.-)%% and causes your Mage Fire spells to grant a stack of Astral Flare%.%s*$","O dano de seus feitiços Bola de Fogo e Explosão Solar aumenta em {{1}}% e faz com que seus feitiços de fogo concedam um acúmulo de Flama Astral."}
T[18787]={"^|cffffffffStarcall|r now consumes |cff66ccffScattered Stars|r from all enemies struck%.%s*$","|cffffffffChamado Estelar|r agora consome |cff66ccffEstrelas Dispersas|r de todos os inimigos atingidos."}
T[18868]={"^Starsunder has a (.-)%% increased chance to apply a Scattered Star and deals (.-)%% increased damage%.%s*$","Estrelhasombra tem uma chance aumentada em {{1}}% de aplicar Estrelas dispersas e causa dano adicional de {{2}}%."}
T[18869]={"^Starsunder has a (.-)%% increased chance to apply a Scattered Star%.%s*$","Estrelhasombra tem uma chance aumentada em {{1}}% de aplicar Estrelas dispersas."}
T[18925]={"^Each tick of |cffffffffSlipstream|r now causes sharks to jump out of the pool at nearby enemies, causing (.-) Frost damage%.%s*$","Cada pulso de |cffffffffCorrente de Ar|r faz tubarões saltarem da água contra inimigos próximos, causando {{1}} de dano de Gelo."}
T[19274]={"^Increases damage of Aspect of the Warden by (.-)%.%s*$","Aumenta o dano do Aspecto dá Guardião em {{1}}."}
T[19310]={"^Your Celestial Strike ability consumes 1 stack of this to incur no cooldown%.%s*$","Sua habilidade Celestial Acerto consome 1 acúmulo desta para não ter recarga."}
T[19364]={"^Your Starsunder deals an additional (.-) Weapon Damage%. Stacks 5 times%.%s*$","Seu Estrelhasombra causa dano da arma adicional de {{1}}. Acumula 5 vezes."}
T[19366]={"^Increases the damage of your |cffffffffLunar Lance|r by (.-)%%%.%s*$","Aumenta o dano de seu |cffffffffLança Lunar|r em {{1}}%."}
T[19367]={"^Causes you to call down an Astral Flare on enemies whenever you dodge, block or parry one of their attacks%. In addition, all damage you take is reduced by (.-)%%, and all Threat generated by Physical and Arcane damage is increased by (.-)%%%.\n\nOnly 1 Aspect can be active at a time%.%s*$","Faz você lançar uma |cffffffffLabareda Astral|r contra inimigos sempre que esquiva, bloqueia ou apara um ataque. Além disso, reduz em {{1}}% todo o dano recebido e aumenta em {{2}}% a ameaça gerada por dano Físico e Arcano.\n\nApenas 1 Aspecto pode estar ativo por vez."}
T[19369]={"^Whenever you are healed, you have a 25%% chance to enable your Vengeance of Elune ability for (.-)%.%s*$","Sempre que te curem, tem 25% de chance de habilitar seu Vingança de Elune durante {{1}}."}
T[20432]={"^For 6 seconds your |cFFFFFFFFWrath|r casts call down a star onto the target dealing Nature damage%.%s*$","Durante os próximos 6 segundos, seus |cFFFFFFFFIra|r Xamã uma estrela sobre o alvo causando dano de Natureza."}
T[20433]={"^|cFFFFFFFFStarfire:|r Your next Starfire hits 2 additional targets%.%s*$","|cFFFFFFFFLança-chamas:|r Seu próximo Lança-chamas impacta 2 alvos adicionais."}
T[20434]={"^Starfire casts will hit 2 additional targets and has 20%% reduced cast time%.%s*$","Fogo Estelar atinge 2 alvos adicionais e tem o tempo de lançamento reduzido em 20%."}
T[20436]={"^Req for Starcaller %(Solar%)%s*$","Req para Chamacorvos (Solar)."}
T[20437]={"^Your Wrath casts calls down a starshard onto the target dealing (.-) Nature damage%.%s*$","Seu lançamento de Fúria chama uma estrela sobre o alvo causando {{1}} de dano de Natureza."}
T[21650]={"^Asleep%.%s*$","Dormindo"}
T[22821]={"^Damage taken is reduced by (.-)%%%.%s*$","O dano recebido é reduzido em {{1}}%."}
T[26095]={"^Gives effective healing on you and any damage dealt by |cffffffffStarsunder|r a 15%% chance to enable you to use |cffffffffVengeance of Elune|r for a short time%.%s*$","A cura efetiva recebida e qualquer dano causado por |cffffffffRompe-estrelas|r têm 15% de chance de permitir o uso de |cffffffffVingança de Elune|r por um curto período."}

